void t2_f_CHECKCHEAT(void)
{
	BX = D_ALFA_KEYS;	/* MOV bx,offset alfa_keys */
	AL = RD8(DS, D_SCAN_CODE);	/* MOV al,scan_code */
	CMP8(AL, 0xFF, FL_ALL);	/* CMP al,-1 */
	if (C_E) goto L_NOVALIDKEY;	/* JE novalidkey */
	XOR8(AH, AH, FL_NONE);	/* XOR ah,ah */
	XLAT(DS);	/* XLAT */
	CMP8(AL, 0, FL_ALL);	/* CMP al,0 */
	if (C_E) goto L_NOVALIDKEY;	/* JE novalidkey */
	WR8(DS, D_DENSOMSPARHANHAR, AL);	/* MOV densomsparhanhar,al */
	PUSH16(SEG_DATA);	/* PUSH data */
	ES = POP16();	/* POP es */
	WR8(DS, D_SCAN_CODE, 0xFF);	/* MOV scan_code,-1 */
	BX = RD16(DS, D_CHEATPEKARE);	/* MOV bx,cheatpekare */
	WR8(DS, (uint16_t)(BX + D_CHEATINPUT), AL);	/* MOV [bx+offset cheatinput],al */
	{ uint16_t ea_ = D_CHEATPEKARE; uint16_t t_ = RD16(DS, ea_); INC16(t_, FL_NONE); WR16(DS, ea_, t_); }	/* INC cheatpekare */
	{ uint16_t t_ = RD16(DS, D_CHEATPEKARE); CMP16(t_, 0xC, FL_ALL); }	/* CMP cheatpekare,12 */
	if (C_BE) goto L_EATIT;	/* JBE eatit */
	WR16(DS, D_CHEATPEKARE, 0);	/* MOV cheatpekare,0 */
	CX = 0xC;	/* MOV cx,12 */
	DI = D_CHEATINPUT;	/* MOV di,offset cheatinput */
	AL = 0x20;	/* MOV al,' ' */
	x_rep_stosb();	/* STOSB */
	RETURN_NEAR(0);	/* RETN */
L_EATIT:;
	SI = D_CHEATS;	/* MOV si,offset cheats */
	WR8(DS, D_DONT_KNOW_YET, 0);	/* MOV dont_know_yet,false */
L_CHECKIT:;
	DI = D_CHEATINPUT;	/* MOV di,offset cheatinput */
	x_lodsw(DS);	/* LODSW */
	CMP16(AX, 0xFF, (FL_Z));	/* CMP ax,255 */
	if (C_E) goto L_ENDOFCHEATS;	/* JE endofcheats */
	BX = AX;	/* MOV bx,ax */
	DX = 0;	/* MOV dx,0 */
L_NEXTTEST:;
	x_lodsb(DS);	/* LODSB */
	CMP8(AL, 0x24, FL_ALL);	/* CMP al,'$' */
	if (C_E) goto L_FOUND;	/* JE found */
	CMP16(DX, RD16(DS, D_CHEATPEKARE), (FL_C));	/* CMP dx,cheatpekare */
	if (C_AE) goto L_NOWNAAAATING;	/* JAE nownaaaating */
	INC16(DX, FL_NONE);	/* INC dx */
	CMP8(AL, RD8(DS, (uint16_t)(DI)), (FL_Z));	/* CMP al,[di] */
	if (C_NE) goto L_NOTFOUND;	/* JNE notfound */
	INC16(DI, FL_NONE);	/* INC di */
	{ X_POLL(); goto L_NEXTTEST; }	/* JMP nexttest */
L_NOWNAAAATING:;
	WR8(DS, D_DONT_KNOW_YET, 0xFF);	/* MOV dont_know_yet,true */
L_NOTFOUND:;
	x_lodsb(DS);	/* LODSB */
	CMP8(AL, 0x24, (FL_Z));	/* CMP al,'$' */
	if (C_E) { X_POLL(); goto L_CHECKIT; }	/* JE checkit */
	{ X_POLL(); goto L_NOTFOUND; }	/* JMP notfound */
L_ENDOFCHEATS:;
	{ uint8_t t_ = RD8(DS, D_DONT_KNOW_YET); CMP8(t_, 0xFF, FL_ALL); }	/* CMP dont_know_yet,true */
	if (C_E) goto L_NOREZZA_OFIT;	/* JE norezza_ofit */
	WR16(DS, D_CHEATPEKARE, 1);	/* MOV cheatpekare,1 */
	CX = 0xB;	/* MOV cx,11 */
	DI = D_CHEATINPUT;	/* MOV di,offset cheatinput */
	AL = RD8(DS, D_DENSOMSPARHANHAR);	/* MOV al,densomsparhanhar */
	x_stosb();	/* STOSB */
	AL = 0x20;	/* MOV al,' ' */
	x_rep_stosb();	/* STOSB */
L_NOREZZA_OFIT:;
	RETURN_NEAR(0);	/* RETN */
L_NOVALIDKEY:;
	RETURN_NEAR(0);	/* RETN */
L_FOUND:;
	WR16(DS, D_CHEATPEKARE, 0);	/* MOV cheatpekare,0 */
	CALLPTR(x_dispatch(CS, BX), 0xE04);	/* CALL bx */
	RETURN_NEAR(0);	/* RETN */
}

