	IDIV16(CX);	/* IDIV CX */
	WR16(DS, (uint16_t)(BX + 0x28), AX);	/* MOV [BX].FLIPMAXHASTUP,AX */
	AX = 5;	/* MOV AX,5 */
	IMUL16(RD16(DS, (uint16_t)(BX + 0x2A)));	/* IMUL [BX].FLIPMAXHASTDOWN */
	CX = 6;	/* MOV CX,6 */
	IDIV16(CX);	/* IDIV CX */
	WR16(DS, (uint16_t)(BX + 0x2A), AX);	/* MOV [BX].FLIPMAXHASTDOWN,AX */
	AX = 5;	/* MOV AX,5 */
	IMUL16(RD16(DS, (uint16_t)(BX + 0x60)));	/* IMUL [BX+FAN].FLIPAXUP */
	CX = 6;	/* MOV CX,6 */
	IDIV16(CX);	/* IDIV CX */
	WR16(DS, (uint16_t)(BX + 0x60), AX);	/* MOV [BX+FAN].FLIPAXUP,AX */
	AX = 5;	/* MOV AX,5 */
	IMUL16(RD16(DS, (uint16_t)(BX + 0x62)));	/* IMUL [BX+FAN].FLIPAXDOWN */
	CX = 6;	/* MOV CX,6 */
	IDIV16(CX);	/* IDIV CX */
	WR16(DS, (uint16_t)(BX + 0x62), AX);	/* MOV [BX+FAN].FLIPAXDOWN,AX */
	AX = 5;	/* MOV AX,5 */
	IMUL16(RD16(DS, (uint16_t)(BX + 0x64)));	/* IMUL [BX+FAN].FLIPMAXHASTUP */
