	CX = 6;	/* MOV CX,6 */
	IDIV16(CX);	/* IDIV CX */
	WR16(DS, (uint16_t)(BX + 0x66), AX);	/* MOV [BX+FAN].FLIPMAXHASTDOWN,AX */
