	CX = 6;	/* MOV CX,6 */
	IDIV16(CX);	/* IDIV CX */
	WR16(DS, (uint16_t)(BX + 0x9C), AX);	/* MOV [BX+FAN*2].FLIPAXUP,AX */
	AX = 5;	/* MOV AX,5 */
