	AX = 5;	/* MOV AX,5 */
	IMUL16(RD16(DS, (uint16_t)(BX + 0xA0)));	/* IMUL [BX+(FAN)*2].FLIPMAXHASTUP */
	CX = 6;	/* MOV CX,6 */
	IDIV16(CX);	/* IDIV CX */
	WR16(DS, (uint16_t)(BX + 0xA0), AX);	/* MOV [BX+(FAN)*2].FLIPMAXHASTUP,AX */
	AX = 5;	/* MOV AX,5 */
	IMUL16(RD16(DS, (uint16_t)(BX + 0xA2)));	/* IMUL [BX+(FAN)*2].FLIPMAXHASTDOWN */
	CX = 6;	/* MOV CX,6 */
	IDIV16(CX);	/* IDIV CX */
	WR16(DS, (uint16_t)(BX + 0xA2), AX);	/* MOV [BX+(FAN)*2].FLIPMAXHASTDOWN,AX */
L_NOSK56:;
	{ uint16_t ea_ = (uint16_t)(BX + 0x72); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 8, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].fliptab,8 */
	{ uint16_t ea_ = (uint16_t)(BX + 0x6E); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 8, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].fliptoppek,8 */
	{ uint16_t ea_ = (uint16_t)(BX + 0x70); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 8, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].flippek,8 */
	{ uint16_t ea_ = (uint16_t)(BX + 0x6C); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 8, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].flipmaxpek,8 */
	PUSH16(BX);	/* PUSH bx */
	ADD16(BX, 0x3C, FL_NONE);	/* ADD bx,size flipstruc */
	{ uint16_t ea_ = (uint16_t)(BX + 0x72); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 0x10, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].fliptab,8*2 */
	{ uint16_t ea_ = (uint16_t)(BX + 0x6E); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 0x10, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].fliptoppek,8*2 */
	{ uint16_t ea_ = (uint16_t)(BX + 0x70); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 0x10, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].flippek,8*2 */
	{ uint16_t ea_ = (uint16_t)(BX + 0x6C); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 0x10, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].flipmaxpek,8*2 */
	BX = POP16();	/* POP bx */
L_MASKAR:;
	{ uint8_t t_ = RD8(DS, (uint16_t)(BX)); CMP8(t_, 0, FL_ALL); }	/* CMP [BX].TYP,0 */
	if (C_E) goto L_INGA_FLER_MASKAR;	/* JZ INGA_FLER_MASKAR */
	WR8(DS, (uint16_t)(BX + 0x1), 0xFF);	/* MOV [bx].lastframe,-1 */
	AX = RD16(DS, (uint16_t)(BX + 0x18));	/* MOV ax,[bx].flipsize */
	CX = 3;	/* MOV cx,3 */
	XOR16(DX, DX, FL_ALL);	/* XOR dx,dx */
	DIV16(CX);	/* DIV cx */
	WR16(DS, (uint16_t)(BX + 0x18), AX);	/* MOV [bx].flipsize,ax */
	PUSH16(BX);	/* PUSH BX */
