	CALLN(t2_f_MOVEFLIPMASK, 0x1092);	/* CALL MOVEFLIPMASK */
	BX = POP16();	/* POP BX */
	ADD16(BX, 0x3C, FL_NONE);	/* ADD BX,SIZE FLIPstruc */
	{ X_POLL(); goto L_MASKAR; }	/* JMP MASKAR */
L_INGA_FLER_MASKAR:;
