void t2_f_NODOT(void)
{
	{ uint8_t t_ = RD8(CS, D_KEYBOARD_ENABLED); CMP8(t_, 0, FL_ALL); }	/* CMP cs:keyboard_enabled,false */
	if (C_E) goto L_I_SHOW_NAAATHING;	/* JE i_show_naaathing */
	{ uint16_t t_ = RD16(DS, D_NODOTCOUNT); CMP16(t_, 0x2D0, (FL_Z)); }	/* CMP NODOTCOUNT,NOT_PLAYING */
	if (C_E) goto L_SHOW_HI_ETC;	/* JE SHOW_HI_ETC */
	{ uint8_t t_ = RD8(DS, D_AFTER_CHEAT); CMP8(t_, 0xFF, FL_ALL); }	/* CMP AFTER_CHEAT,TRUE */
	if (C_E) goto L_CHEATED;	/* JE CHEATED */
	{ uint8_t t_ = RD8(DS, D_DEMOMODE); CMP8(t_, 0xFF, FL_ALL); }	/* CMP DEMOMODE,TRUE */
	if (C_E) goto L_SHOW_HI_2;	/* JE SHOW_HI_2 */
	{ uint8_t t_ = RD8(DS, D_I_UTSKJUT); CMP8(t_, 0xFF, FL_ALL); }	/* CMP I_UTSKJUT,TRUE */
	if (C_E) goto L_ONLY_SCORE;	/* JE ONLY_SCORE */
	{ uint8_t t_ = RD8(DS, D_BEHOVS_PROVAD); CMP8(t_, 0xFF, FL_ALL); }	/* CMP behovs_provad,true */
	if (C_NE) goto L_ONLY_SCORE;	/* JNE only_score */
	WR8(DS, D_BEHOVS_PROVAD, 0);	/* MOV behovs_provad,false */
	BX = D_SHOWPLAYERSTS;	/* MOV BX,OFFSET showplayersTS */
	CALLN(t2_f_DO_SPEC_MATRIX, 0x19F1);	/* CALL DO_SPEC_MATRIX */
	goto L_ONLY_SCORE;	/* JMP ONLY_SCORE */
L_CHEATED:;
	WR8(DS, D_AFTER_CHEAT, 0);	/* MOV AFTER_CHEAT,FALSE */
	BX = D_SHOWHIGHSTS;	/* MOV BX,OFFSET showHighSTS */
	CALLN(t2_f_DO_MATRIX, 0x19F5);	/* CALL DO_MATRIX */
	goto L_I_SHOW_NAAATHING;	/* JMP i_show_naaathing */
L_SHOW_HI_ETC:;
	{ uint8_t t_ = RD8(DS, D_SPRING_VALID); CMP8(t_, 0xFF, FL_ALL); }	/* CMP spring_valid,true */
	if (C_E) goto L_OVERITAGAIN;	/* JE overitagain */
	WR16(DS, D_FJANTTEXT, 0xFF);	/* MOV fjanttext,true */
	AL = RD8(DS, (uint16_t)(D_PLAYERSTEXT + 7));	/* MOV AL,playerstext[7] */
	WR8(DS, (uint16_t)(D_PLAY_TEXT + 8), AL);	/* MOV play_text[8],AL */
	AL = RD8(DS, (uint16_t)(D_BALLSTEXT + 5));	/* MOV AL,ballstext[5] */
	WR8(DS, (uint16_t)(D_PLAY_TEXT + 18), AL);	/* MOV play_text[18],AL */
	BX = D_SHOWINFOTS;	/* MOV BX,OFFSET showInfoTS */
	CALLN(t2_f_DO_MATRIX, 0x19FF);	/* CALL DO_MATRIX */
	goto L_OVERITAGAIN;	/* JMP OVERITAGAIN */
L_SHOW_HI_2:;
	BX = D_AFTERDEMOMODETS;	/* MOV BX,OFFSET AfterDemoModeTS */
	CALLN(t2_f_DO_MATRIX, 0x1A02);	/* CALL DO_MATRIX */
	goto L_OVERITAGAIN;	/* JMP overitagain */
	WR8(DS, D_FIRST_TIME_YOU_FOOL, 0);	/* MOV first_time_you_fool,false */
	BX = D_SHOWHIGHSTS;	/* MOV BX,OFFSET showHighSTS */
	CALLN(t2_f_DO_MATRIX, 0x1A06);	/* CALL DO_MATRIX */
L_OVERITAGAIN:;
L_ONLY_SCORE:;
	CALLN(t2_f_CHECKHIGHSCORE, 0x1A07);	/* CALL CHECKHIGHSCORE */
	{ uint16_t ea_ = D_NODOTCOUNT; uint16_t t_ = RD16(DS, ea_); INC16(t_, (FL_Z | FL_S | FL_O | FL_P | FL_A)); WR16(DS, ea_, t_); }	/* INC NODOTCOUNT */
	SI = D_SIFFRORNA;	/* MOV si,offset siffrorna */
	BX = 0xC8;	/* MOV bx,SW*2/4+(320-12*16)/4 */
	PUSH16(CS);	/* PUSH CS */
	ES = POP16();	/* POP ES */
	CALLFARPTR(ES, D_PEKOR, 0x1A0D);	/* CALL DWORD PTR ES:PEKOR */
L_I_SHOW_NAAATHING:;
	SI = 0;	/* MOV SI,0 */
	RETURN_NEAR(0);	/* RETN */
}

void t2_f_CHECKHIGHSCORE(void)
{
	PUSHA();	/* PUSHA */
	{ uint8_t t_ = RD8(DS, D_I_UTSKJUT); CMP8(t_, 0xFF, FL_ALL); }	/* CMP i_utskjut,true */
	if (C_E) goto L_END_CHKOFHISCRE;	/* JE end_chkofhiscre */
	{ uint8_t t_ = RD8(DS, D_SPECIALMODE); CMP8(t_, 0xFF, FL_ALL); }	/* CMP specialmode,true */
	if (C_E) goto L_END_CHKOFHISCRE;	/* JE end_chkofhiscre */
	{ uint8_t t_ = RD8(DS, D_ALREADY_BEATEN); CMP8(t_, 0xFF, FL_ALL); }	/* CMP already_beaten,true */
	if (C_E) goto L_END_CHKOFHISCRE;	/* JE end_chkofhiscre */
	DI = D_HI_SCORE_LIST;	/* MOV di,offset hi_score_list */
	SI = D_SIFFRORNA;	/* MOV SI,OFFSET SIFFRORNA */
	CX = 0xC;	/* MOV cx,12 */
	BX = 0;	/* MOV bx,0 */
L_HCHECK_NUM:;
	AL = RD8(DS, (uint16_t)(DI + BX));	/* MOV al,[di+bx] */
	{ uint8_t t_ = RD8(DS, (uint16_t)(SI + BX)); CMP8(t_, AL, FL_ALL); }	/* CMP [si+bx],al */
	if (C_B) goto L_HNOT_BEATEN;	/* JB Hnot_beaten */
	if (C_A) goto L_HBEATEN;	/* JA Hbeaten */
	INC16(BX, (FL_Z | FL_S | FL_O | FL_P | FL_A));	/* INC bx */
	CX = (uint16_t)(CX - 1);	/* LOOP Hcheck_num */
	if (CX != 0) { X_POLL(); goto L_HCHECK_NUM; }
L_HNOT_BEATEN:;
L_END_CHKOFHISCRE:;
	POPA();	/* POPA */
	RETURN_NEAR(0);	/* RETN */
L_HBEATEN:;
	WR8(DS, D_ALREADY_BEATEN, 0xFF);	/* MOV already_beaten,true */
	BX = D_BEATENTS;	/* MOV BX,OFFSET BEATENTS */
	CALLN(t2_f_DO_MATRIX, 0x1A25);	/* CALL DO_MATRIX */
	WR8(DS, D_BEHOVS_PROVAD, 0xFF);	/* MOV behovs_provad,true */
	POPA();	/* POPA */
	RETURN_NEAR(0);	/* RETN */
}

void t2_f__BEATEN_MATRIX(void)
{
	PUSHA();	/* PUSHA */
	{ uint8_t t_ = RD8(DS, D_ALREADY_BEATEN); CMP8(t_, 0xFF, (FL_Z)); }	/* CMP already_beaten,true */
	if (C_E) goto L_BEND_CHKOFHISCRE;	/* JE bend_chkofhiscre */
	DI = D_HI_SCORE_LIST;	/* MOV di,offset hi_score_list */
	SI = D_SIFFRORNA;	/* MOV SI,OFFSET SIFFRORNA */
	CX = 0xC;	/* MOV cx,12 */
	BX = 0;	/* MOV bx,0 */
L_BHCHECK_NUM:;
	AL = RD8(DS, (uint16_t)(DI + BX));	/* MOV al,[di+bx] */
	{ uint8_t t_ = RD8(DS, (uint16_t)(SI + BX)); CMP8(t_, AL, FL_ALL); }	/* CMP [si+bx],al */
	if (C_B) goto L_BHNOT_BEATEN;	/* JB bHnot_beaten */
	if (C_A) goto L_BHBEATEN;	/* JA bHbeaten */
	INC16(BX, FL_NONE);	/* INC bx */
	CX = (uint16_t)(CX - 1);	/* LOOP bHcheck_num */
	if (CX != 0) { X_POLL(); goto L_BHCHECK_NUM; }
L_BHNOT_BEATEN:;
L_BEND_CHKOFHISCRE:;
	POPA();	/* POPA */
	ADD16(BX, 2, FL_ALL);	/* ADD bx,2 */
	TAILPTR(x_dispatch(CS, RD16(DS, (uint16_t)(BX))));	/* JMP [bx] */
L_BHBEATEN:;
	WR8(DS, D_ALREADY_BEATEN, 0xFF);	/* MOV already_beaten,true */
	POPA();	/* POPA */
	BX = D_BEATEN_BH_TS;	/* MOV bx,offset beaten_bh_ts */
	TAILPTR(x_dispatch(CS, RD16(DS, (uint16_t)(BX))));	/* JMP [BX] */
	SI = RD16(DS, D_SI_SIFFROR);	/* MOV si,si_siffror */
	DI = RD16(DS, D_DI_SIFFROR);	/* MOV di,di_siffror */
	WR16(DS, D_HOJD_1, 5);	/* MOV hojd_1,5 */
	WR16(DS, D_HOJD_ADD, 0xFCBC);	/* MOV hojd_add,bredd_1/4-sw*5*2/4 */
	WR16(DS, D_FONT_ADR, D_FONT5);	/* MOV font_adr,offset font5 */
	CALLN(t2_f_PRINT_NUMBER, 0x1A42);	/* CALL print_number */
	SI = RD16(DS, D_SI_SIFFROR);	/* MOV si,si_siffror */
	DI = RD16(DS, D_DI_SIFFROR);	/* MOV di,di_siffror */
	WR16(DS, D_HOJD_1, 5);	/* MOV hojd_1,5 */
	WR16(DS, D_HOJD_ADD, 0xFCBC);	/* MOV hojd_add,bredd_1/4-sw*5*2/4 */
	WR16(DS, D_FONT_ADR, D_FONT5);	/* MOV font_adr,offset font5 */
	CALLN(t2_f_PRINT_NUMBER, 0x1A48);	/* CALL print_number */
	{ X_POLL(); TAIL(t2_f_DOSUICIDE); }	/* JMP DOSUICIDE */
	WR16(DS, D_HOJD_1, 8);	/* MOV hojd_1,8 */
	WR16(DS, D_HOJD_ADD, 0xFAC4);	/* MOV hojd_add,bredd_1/4-sw*8*2/4 */
	WR16(DS, D_FONT_ADR, D_FONT8);	/* MOV font_adr,offset font8 */
	CALLN(t2_f_PRINT_NUMBER, 0x1A4D);	/* CALL print_number */
	RETURN_NEAR(0);	/* RETN */
	WR16(DS, D_HOJD_1, 0xB);	/* MOV hojd_1,11 */
	WR16(DS, D_HOJD_ADD, 0xF8CC);	/* MOV hojd_add,bredd_1/4-sw*11*2/4 */
	WR16(DS, D_FONT_ADR, D_FONT11);	/* MOV font_adr,offset font11 */
	CALLN(t2_f_PRINT_NUMBER, 0x1A52);	/* CALL print_number */
	RETURN_NEAR(0);	/* RETN */
	WR16(DS, D_HOJD_1, 0xD);	/* MOV hojd_1,13 */
	WR16(DS, D_HOJD_ADD, 0xF77C);	/* MOV hojd_add,bredd_1/4-sw*13*2/4 */
	WR16(DS, D_FONT_ADR, D_FONT13);	/* MOV font_adr,offset font13 */
	CALLN(t2_f_PRINT_NUMBER, 0x1A57);	/* CALL print_number */
	RETURN_NEAR(0);	/* RETN */
}

void t2_f_FLIPPRA(void)
{
	PUSH16(0xA000);	/* PUSH 0A000H */
	ES = POP16();	/* POP ES */
	DX = 0x3C4;	/* MOV DX,3C4H */
	AX = 0xF02;	/* MOV AX,0F02H */
	OUT16(DX, AX);	/* OUT DX,AX */
	DX = 0x3CE;	/* MOV DX,3CEH */
	AX = 0x4105;	/* MOV AX,4105H */
	OUT16(DX, AX);	/* OUT DX,AX */
	AX = RD16(DS, (uint16_t)(BX + 0x4));	/* MOV AX,[BX].TOPY */
	ADD16(AX, 0x21, FL_NONE);	/* ADD AX,SPLH */
	DI = 0x54;	/* MOV DI,BPL */
	MUL16(DI);	/* MUL DI */
	DI = AX;	/* MOV DI,AX */
	AX = RD16(DS, (uint16_t)(BX + 0x2));	/* MOV AX,[BX].LEFTX */
	SHR16(AX, 2, FL_NONE);	/* SHR AX,2 */
	ADD16(DI, AX, FL_NONE);	/* ADD DI,AX */
	AX = RD16(DS, (uint16_t)(BX + 0x1E));	/* MOV AX,[BX].FLIPFRAME */
	CX = AX;	/* MOV CX,AX */
	SUB16(CX, RD16(DS, (uint16_t)(BX + 0x2C)), FL_ALL);	/* SUB CX,[BX].LASTGFXFRAME */
	{ uint16_t ea_ = (uint16_t)(BX + 0x2C); uint16_t t_ = RD16(DS, ea_); WR16(DS, ea_, AX); AX = t_; }	/* XCHG [BX].LASTGFXFRAME,AX */
	if (C_E) { X_POLL(); TAIL(t2_f_NOMOVE); }	/* JE NOMOVE */
	if (C_A) goto L_WAYUP;	/* JA WAYUP */
	NEG16(CX, FL_NONE);	/* NEG CX */
	DX = RD16(DS, (uint16_t)(BX + 0x38));	/* MOV DX,[BX].FLIPDIFS */
	MUL16(DX);	/* MUL DX */
	PUSH16(RD16(DS, (uint16_t)(BX + 0x30)));	/* PUSH [BX].FLIPMAXPEK */
	WR16(DS, (uint16_t)(BX + 0x34), POP16());	/* POP [BX].FLIPPEK */
	{ uint16_t ea_ = (uint16_t)(BX + 0x34); uint16_t t_ = RD16(DS, ea_); SUB16(t_, AX, FL_NONE); WR16(DS, ea_, t_); }	/* SUB [BX].FLIPPEK,AX */
	goto L_DANIM;	/* JMP DANIM */
L_WAYUP:;
	DX = RD16(DS, (uint16_t)(BX + 0x38));	/* MOV DX,[BX].FLIPDIFS */
	MUL16(DX);	/* MUL DX */
	ADD16(AX, RD16(DS, (uint16_t)(BX + 0x36)), FL_NONE);	/* ADD AX,[BX].FLIPTAB */
	WR16(DS, (uint16_t)(BX + 0x34), AX);	/* MOV [BX].FLIPPEK,AX */
L_DANIM:;
	PUSH16(0);	/* PUSH 0 */
	CMP16(CX, 9, (FL_C | FL_Z));	/* CMP CX,9 */
	if (C_BE) goto L_DELTA_ANIMERA;	/* JBE DELTA_ANIMERA */
	AX = POP16();	/* POP AX */
	AX = CX;	/* MOV AX,CX */
	SUB16(AX, 9, FL_NONE);	/* SUB AX,9 */
	PUSH16(AX);	/* PUSH AX */
	CX = 9;	/* MOV CX,9 */
L_DELTA_ANIMERA:;
	PUSH16(CX);	/* PUSH CX */
	PUSH16(DI);	/* PUSH DI */
	PUSH16(BX);	/* PUSH BX */
	BX = RD16(DS, (uint16_t)(BX + 0x34));	/* MOV BX,[BX].FLIPPEK */
	AX = SEG_DATAFLIP;	/* MOV AX,DATAFLIP */
	DS = AX;	/* MOV DS,AX */
	SI = CX;	/* MOV si,cx */
	DEC16(SI, FL_NONE);	/* DEC si */
	SHL16(SI, 1, FL_NONE);	/* SHL si,1 */
	CX = RD16(DS, (uint16_t)(BX + SI));	/* MOV CX,[BX+si] */
	if (CX == 0) goto L_NOBYTESTOANIM;	/* JCXZ nobytestoanim */
	ADD16(BX, 0x12, FL_ALL);	/* ADD BX,2*9 */
	CALLN(t2_f_DELTANIM, 0x1A92);	/* CALL DELTANIM */
L_NOBYTESTOANIM:;
	AX = SEG_DATA;	/* MOV AX,DATA */
	DS = AX;	/* MOV DS,AX */
	BX = POP16();	/* POP BX */
	AX = RD16(DS, (uint16_t)(BX + 0x38));	/* MOV AX,[BX].FLIPDIFS */
	{ uint16_t ea_ = (uint16_t)(BX + 0x34); uint16_t t_ = RD16(DS, ea_); ADD16(t_, AX, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [BX].FLIPPEK,AX */
	DI = POP16();	/* POP DI */
	CX = POP16();	/* POP CX */
	CX = (uint16_t)(CX - 1);	/* LOOP DELTA_ANIMERA */
	if (CX != 0) { X_POLL(); goto L_DELTA_ANIMERA; }
	CX = POP16();	/* POP CX */
	OR16(CX, CX, FL_ALL);	/* OR CX,CX */
	PUSH16(0);	/* PUSH 0 */
	if (C_NE) { X_POLL(); goto L_DELTA_ANIMERA; }	/* JNZ DELTA_ANIMERA */
	AX = POP16();	/* POP AX */
	TAIL(t2_f_NOMOVE);
}

void t2_f_NOMOVE(void)
{
	DX = 0x3CE;	/* MOV DX,3CEH */
	AX = 0x4005;	/* MOV AX,4005H */
	OUT16(DX, AX);	/* OUT DX,AX */
	RETURN_NEAR(0);	/* RETN */
}

