	goto L_KUKENKARL;	/* JMP kukenkarl */
L_NILSBEDRUPP:;
	AX = 0xFF5A;	/* MOV ax,(-5000/15)/2 */
L_KUKENKARL:;
	IMUL16(CX);	/* IMUL Cx */
	BP = AX;	/* MOV bp,ax */
	AX = RD16(DS, D_SLUMP_COUNTERN);	/* MOV ax,slump_countern */
	AND16(AX, 0xFF, FL_NONE);	/* AND ax,255 */
	SUB16(BP, AX, FL_NONE);	/* SUB bp,ax */
	{ uint8_t t_ = RD8(DS, D_MAKE_BAD); CMP8(t_, 0xFF, (FL_Z)); }	/* CMP MAKE_BAD,TRUE */
	if (C_E) goto L_BADDAREN;	/* JE BADDAREN */
	WR16(DS, D_Y_HAST, BP);	/* MOV Y_HAST,bp */
	WR16(DS, D_X_HAST, 0);	/* MOV X_HAST,0 */
	WR16(DS, D_ROTATION, 0);	/* MOV ROTATION,0 */
L_BADDAREN:;
	AX = RD16(DS, D_SLUMP_COUNTERN);	/* MOV AX,slump_countern */
	WR16(DS, D_ROTATION, AX);	/* MOV rotation,AX */
	{ uint16_t ea_ = D_ROTATION; uint16_t t_ = RD16(DS, ea_); AND16(t_, 0xF, FL_NONE); WR16(DS, ea_, t_); }	/* AND rotation,15 */
L_DOUP2:;
	AL = RD8(DS, D_SPRINGPOS);	/* MOV AL,SPRINGPOS */
	XOR8(AH, AH, FL_NONE);	/* XOR AH,AH */
	SHL16(AX, 6, (FL_C));	/* SHL AX,6 */
	BL = 0x20;	/* MOV BL,(SPRINGH-1)*2 */
